interface.definition:
a!localVariables(

  #"SYSTEM_SYSRULES_formLayout_v2"(
    contents: {
      #"_a-0000eef8-4604-8000-9e54-011c48011c48_1134085"(selectedteams: ri!selectedteams,selectable: true())
    },
    buttons: #"SYSTEM_SYSRULES_ButtonLayout"(
      primaryButtons: {
        #"SYSTEM_SYSRULES_buttonWidget_v1"(
          label: "Submit",
          submit: true,
          saveInto: {
            a!save(
              target:ri!button,
              value: #"_a-0000eeda-0177-8000-9e52-011c48011c48_1085463"
            )
          },
          loadingIndicator: true,
          style: "SOLID"
        )
      },
      secondaryButtons: {
        #"SYSTEM_SYSRULES_buttonWidget_v1"(
          label: "Cancel",
          value: true,
          saveInto: {
            a!save(
              target:ri!button,
              value:#"_a-0000eeda-0177-8000-9e52-011c48011c48_1085469"
            )
          },
          validate: false,
          submit: true,
          style: "OUTLINE"
        )
      }
    ),
    titleBar: #"SYSTEM_SYSRULES_headerTemplateFull"(
      title: "List Of Teams",
      secondaryText: "Select The Teams",
      backgroundColor: "ACCENT"
    ),
    showTitleBarDivider: false
  )
)
